using School.API.DTOs;

namespace School.API.Services.Interfaces
{
    public interface ISmsService
    {
        // Enqueue-only: saves recipients to the DB queue with Status=Pending
        // and returns the jobId + queued count. Actual sending is done by
        // SmsQueueProcessor (background service).
        Task<SmsQueueStatusDto> EnqueueBulkAsync(SmsSendDto dto);
        Task<SmsQueueStatusDto> EnqueueFeeReminderAsync(FeeSmsSendDto dto);

        // Enqueues one Result-Card PDF (WhatsApp document) per matched student.
        // The PDF itself is generated by the background queue at send time.
        Task<SmsQueueStatusDto> EnqueueRcardAsync(RcardSendDto dto);

        // Enqueues each matched student's result as a TEXT message (no PDF).
        // The result text is composed by the background queue at send time.
        Task<SmsQueueStatusDto> EnqueueResultTextAsync(ResultTextSendDto dto);

        Task<SmsQueueStatusDto> GetJobStatusAsync(string jobId);
        Task<int> GetOverallPendingCountAsync();

        Task<IEnumerable<SmsHistoryDto>> GetHistoryAsync(SmsHistoryFilterDto filter);
        Task<int> GetHistoryCountAsync(SmsHistoryFilterDto filter);

        // ── Messages viewer ──────────────────────────────────────────
        // Paged log showing the Meta template used, the parameters sent, the
        // complete rendered message and the delivery outcome for each row.
        Task<SmsMessagePagedDto> GetMessagesAsync(SmsMessageFilterDto filter);
        Task<SmsMessageViewDto?> GetMessageAsync(int vid);

        // Applies a Meta delivery-status webhook payload. Returns how many rows
        // were matched and updated.
        Task<int> ApplyDeliveryWebhookAsync(string rawJson);
        Task<List<SmsRecipientDto>> GetAbsentStudentsAsync(DateTime date);
        Task<List<SmsRecipientDto>> GetLateStudentsAsync(DateTime date);
        Task<List<SmsRecipientDto>> GetFeeDefaultersAsync();
    }
}
